<template><Card class="s45-manager"><template v-if="!$route.params.id"><h2>{{title}}</h2><p class="intro">{{description}}</p><RecordList :endpoint="exceptions?'/exceptions':'/funds'" :params="{kind}" :states="states" :columns="columns" @open="open"/></template><FundsDetail v-else :id="$route.params.id" :task-mode="taskMode" @back="back"/></Card></template>
<script>
import RecordList from './RecordList.vue';import FundsDetail from './FundsDetail.vue';import {money,date,label} from '../presentation.cjs';
const col=(title,key,f)=>({title,key,minWidth:160,...(f?{render:(h,{row})=>h('span',f(row[key]))}:{})});
export default{components:{RecordList,FundsDetail},props:{title:String,description:String,kind:{type:String,default:'PAYMENT'},base:String,exceptions:Boolean},computed:{taskMode(){return this.kind!=='PAYMENT'},states(){return this.taskMode?['PENDING','UNKNOWN','PROCESSING','FAILED','SUCCEEDED']:['NOT_STARTED','UNPAID','UNKNOWN','SUCCEEDED','CLOSED']},columns(){return this.taskMode?[col('原订单','orderSn'),col('店铺','storeName'),col('渠道原请求','requestNo'),col('申请金额','amountCent',money),col('渠道成功金额','succeededCent',money),col('资金状态','state',label),{title:'本地回写',minWidth:120,render:(h,{row})=>h('span',row.applied?'已处理':'待处理')},col('最近观察','observedAt',date)]:[col('原合单号','tradeSn'),col('子订单','orderSn'),col('店铺','storeName'),col('本店子单可信实付','paidCent',money),col('所属合单实付（仅核对）','tradePaidCent',money),col('合单子单数','tradeChildCount'),col('付款状态','paymentState',label),col('成功退款','goodsRefundCent',money),col('实际净额','netCent',money),{title:'未决 / 异常',minWidth:160,render:(h,{row})=>h('span',money(row.pendingObligationCent)+' / '+row.exceptionCount+' 项')},col('下单时间','createdAt',date)]}},methods:{open(row){this.$router.push({path:'/s45/'+this.base+'/'+(this.taskMode?row.id:row.orderId),query:this.$route.query})},back(){this.$router.push({path:'/s45/'+this.base,query:this.$route.query})}}};
</script><style lang="scss">@import '../stage45.scss';</style>
